export const MON_LESSONS_LIT_8: LessonData[] = hydrateMonLessons(D, [{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-myths","m":["8-lit:I.1"],"t":"Античност. Старогръцка митология: @@5h@@ за @@j@@ и за Едип","o":"Античност — културата на Древна Гърция и Древен Рим. Мит — @@0@@. @@j@@: огънят и жертвата за @@22@@. Едип: @@2d@@ и търсенето на @@1h@@.","su":{"ov":"@@2u@@ е културната епоха на Древна Гърция и Древен Рим. Тя е основа на @@12@@ @@51@@ — от нея идват философията, театърът, демокрацията и @@3v@@ от литературните родове и жанрове. Митологията е съвкупността от митове: разкази за @@1v@@, @@1y@@ и @@4e@@ на света, чрез които древните хора обясняват @@1p@@ и човешката съдба.","kp":["Светогледни идеи на @@2u@@: многобожие (@@1v@@ са подобни на @@22@@ и се намесват в @@2v@@ им); @@2w@@ и неговото място в света; хармония и красота на @@5i@@ и духа; @@2d@@ (мойрите), на която не може да се избяга.","@@j@@ е титан, @@w@@ открадва огъня от @@1v@@ и го дава на @@22@@. Така им дава възможност за знания, занаяти и @@5j@@. Зевс го наказва: @@j@@ е прикован към скала в Кавказ, а орел всеки ден кълве черния му дроб, @@w@@ израства отново. Освобождава го Херакъл.","@@j@@ е символ на саможертвата за @@22@@, на бунта срещу тиранията и на стремежа към знание и напредък.","Едип е син на тиванския цар Лай. Оракул предсказва, че ще убие баща си и ще се ожени за майка си, затова като бебе е изоставен. Израства в Коринт, без да знае @@4e@@ си. Бягайки от предсказанието, @@2e@@ непознат на пътя — Лай. После решава гатанката на Сфинкса, става цар на Тива и се жени за вдовицата Йокаста — своята майка. Когато научава @@1h@@, Йокаста се самоубива, а Едип се ослепява и тръгва в изгнание.","Митът за Едип @@2f@@ въпросите за @@2d@@ и свободната воля, за вината без умисъл и за мъжеството да търсиш @@1h@@, дори когато тя те унищожава."],"eg":"Когато тълкуваш мит, разкажи накратко сюжета и после кажи каква идея носи: @@j@@ — саможертва и знание, Едип — @@2d@@ и @@1h@@. Оценката идва от @@2x@@, не от преразказа.","ct":["@@j@@ не е бог от Олимп, а титан, @@w@@ застава на страната на @@22@@ срещу Зевс.","Едип не е злодей: той извършва престъпленията, без да знае. Трагичното е, че колкото повече се опитва да избяга от @@2d@@, толкова по-сигурно я изпълнява."],"fd":[{"l":"Античност","v":"ок. VIII в. пр. Хр. – V в. сл. Хр."},{"l":"Мит","v":"@@0@@"},{"l":"@@j@@ в @@1w@@","v":"Есхил, „Прикованият @@j@@“; М. Шели, „Франкенщайн, или модерният @@j@@“ (1818)"},{"l":"Едип в @@1w@@","v":"Софокъл, „Цар Едип“; Енгр, „Едип и Сфинксът“ (1808)"}]},"nc":[{"id":"mon8-lit-myths-chk-1","r":"Двата мита в 5 изречения всеки и по една идея","wn":"@@3l@@ изисква да познаваш съдържанието на @@5h@@.","e6":true,"sn":"@@j@@ → огън → наказание → освобождение → идея за саможертва. Едип → оракул → Сфинкс → истина → идея за @@2d@@."},{"id":"mon8-lit-myths-chk-2","r":"Два примера за @@5h@@ в европейското изкуство","wn":"Изследователската задача по @@3j@@ е свързана с интерпретациите на @@5h@@.","e6":false,"sn":"Творба → автор → @@2t@@ взема от мита."}],"fc":[{"id":"mon8-lit-myths-fc-1","f":"@@l@@ е митология?","b":"Съвкупност от митове — разкази за @@1v@@, @@1y@@ и @@4e@@ на света.","tg":"@@u@@"},{"id":"mon8-lit-myths-fc-2","f":"@@l@@ дава @@j@@ на @@22@@?","b":"Огъня, откраднат от @@1v@@ — а с него и възможност за знание и @@5j@@.","tg":"@@j@@"},{"id":"mon8-lit-myths-fc-3","f":"Как е наказан @@j@@?","b":"Прикован е към скала в Кавказ и орел кълве черния му дроб; @@2y@@ го Херакъл.","tg":"@@j@@"},{"id":"mon8-lit-myths-fc-4","f":"@@l@@ предсказва оракулът за Едип?","b":"Че ще убие баща си и ще се ожени за майка си.","tg":"Едип"},{"id":"mon8-lit-myths-fc-5","f":"Какъв е отговорът на гатанката на Сфинкса?","b":"Човекът — като дете пълзи на четири крака, като възрастен ходи на два, а като старец се подпира на бастун.","tg":"Едип"},{"id":"mon8-lit-myths-fc-6","f":"Коя е @@2z@@ идея на мита за Едип?","b":"Човекът не може да избяга от @@2d@@ си, но може да намери мъжество да приеме @@1h@@.","tg":"Идея"}],"q":[{"id":1,"qu":"@@l@@ е мит?","op":["Разказ за реално събитие с точни дати и места","Разказ за богове и герои, който обяснява света","Кратка поучителна история с животни и морал","Лирическа песен в чест на бог или герой"],"ci":1,"ex":"Митът е древен @@4b@@, чрез @@w@@ @@22@@ обясняват @@1p@@ и @@2d@@."},{"id":2,"qu":"Кой @@2y@@ @@j@@?","op":["Херакъл","Хермес","Персей","Тезей"],"ci":0,"ex":"По мита Херакъл убива орела, който кълве черния дроб на Прометей, и освобождава титана. Хермес е пратеник на Зевс, а Персей и Тезей са герои на други митове."},{"id":3,"qu":"Кой е бащата на Едип?","op":["Креон","Тирезий","Етеокъл","Лай"],"ci":3,"ex":"Бащата на Едип е тиванският цар Лай, а майка му е Йокаста. Креон е брат на Йокаста, Тирезий е слепият прорицател, а Етеокъл е син на Едип."},{"id":4,"qu":"@@4@@","op":["Бунта срещу боговете в името на личната слава","Хитростта, която носи власт над хората","Саможертвата за хората и стремежа към знание","Покорството пред волята на Зевс"],"ci":2,"ex":"@@j@@ поема наказание, за да даде огъня — знанието — на @@22@@."},{"id":5,"qu":"Как Едип става цар на Тива?","op":["Като побеждава Креон в двубой","Като решава гатанката на Сфинкса","Като се жени за дъщерята на царя на Коринт","Като го посочва оракулът в Делфи"],"ci":1,"ex":"Едип става цар на Тива, като решава гатанката на Сфинкса и освобождава града от чудовището; наградата е тронът и ръката на вдовицата Йокаста. Той не побеждава Креон и не е посочен за цар от оракула."},{"id":6,"qu":"Коя @@3m@@ е интерпретация на мита за @@j@@?","op":["„Франкенщайн“ на Мери Шели","„Цар Едип“ на Софокъл","„Одисея“ на Омир","„Медея“ на Еврипид"],"ci":0,"ex":"Романът на Мери Шели (1818) @@5l@@ мита в подзаглавието си."}],"qq":["@@4@@","Защо Едип е трагичен @@4g@@?","Кои са светогледните идеи на @@2u@@?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-iliad","m":["8-lit:I.2"],"t":"„@@2k@@“ (Омир): епос, @@23@@ @@3n@@ и @@5m@@ @@t@@","o":"„@@2k@@“ — епос за 51 дни от десетата година на Троянската война; темата е гневът на Ахил. Откъси: I (свадата), VI (@@13@@ и @@24@@), XXII (двубоят), XXIV (Приам при Ахил).","su":{"ov":"„@@2k@@“ е старогръцки епос, приписван на Омир (около VIII в. пр. Хр.), в 24 песни. Тя @@25@@ не цялата Троянска война, а около 51 дни от десетата ѝ година. Централната ѝ тема е гневът на Ахил и последиците от него. Чрез @@1y@@ @@14@@ @@3w@@ ценностите на античния свят: славата, честта, @@3x@@, приятелството и човечността.","kp":["Троянският цикъл: богинята на раздора Ерида хвърля златна ябълка „за най-красивата“. Парис я дава на Афродита и в замяна @@5k@@ Елена, @@4h@@ на Менелай. Отвличането на Елена е причината ахейците да тръгнат срещу Троя.","Песен I: Агамемнон, предводителят на ахейците, отнема пленницата на Ахил. Обиденият Ахил се оттегля от битките, а майка му Тетида моли Зевс да даде надмощие на троянците.","Песен VI: @@13@@ се среща с жена си @@24@@ и сина си Астианакс. @@24@@ го моли да остане, но той @@4f@@ @@3x@@ към Троя. Детето се плаши от шлема му и @@13@@ го сваля. Сцената @@3w@@ героя като баща и съпруг.","Песен XXII: след като @@13@@ @@2e@@ Патрокъл, приятеля на Ахил, Ахил се връща в боя и @@2e@@ @@13@@ в двубой пред стените на Троя. Песен XXIV: старият цар Приам идва в шатрата на Ахил да откупи @@5i@@ на сина си. Ахил се трогва, като си спомня за собствения си баща, и връща @@5i@@. @@26@@ @@5n@@ с @@4i@@ на @@13@@.","Средства: постоянните епитети се повтарят с имената на @@1y@@ („бързоногият Ахил“) и подчертават неизменния им признак. Епическото @@t@@ е разгърнато, често с @@2s@@ от @@1p@@ (@@4g@@ — лъв, войска — вълни). То забавя @@1q@@ и прави събитието величаво."],"eg":"Песен XXIV е ключът към @@4d@@ на @@14@@: гневът @@3y@@ пред състраданието. Врагът също е @@52@@, @@w@@ обича и страда.","ct":["Троянският кон и падането на Троя не са в „@@2k@@“ — те са част от Троянския цикъл и се разказват в други творби.","Обикновеният @@3n@@ е художествено определение. Постоянният е устойчиво свързан с конкретен @@4g@@ или предмет и се повтаря."],"fd":[{"l":"Автор и @@3z@@","v":"Омир, ок. VIII в. пр. Хр."},{"l":"Обем","v":"24 песни, ~51 дни от 10-ата година на войната"},{"l":"Тема","v":"гневът на Ахил"},{"l":"Епос","v":"@@1z@@ род — @@4b@@ за събития и @@3e@@"},{"l":"Епическо @@t@@","v":"разгърнато @@t@@, често с @@2s@@ от @@1p@@"}]},"nc":[{"id":"mon8-lit-iliad-chk-1","r":"Таблица с @@5o@@ откъса: @@40@@, @@3e@@, ценност","wn":"@@53@@ на изучените откъси е основният @@30@@ @@27@@.","e6":true,"sn":"I — свадата, чест; VI — @@13@@ и @@24@@, дълг и семейство; XXII — двубоят, слава и съдба; XXIV — Приам и Ахил, @@1i@@."},{"id":"mon8-lit-iliad-chk-2","r":"@@54@@: епос, @@3n@@, @@23@@ @@3n@@, @@t@@, @@5m@@ @@t@@","wn":"@@5@@","e6":true,"sn":"Към всяко понятие — по един пример от @@14@@."}],"fc":[{"id":"mon8-lit-iliad-fc-1","f":"@@2b@@ е темата на „@@2k@@“?","b":"Гневът на Ахил и неговите последици по @@3z@@ на Троянската война.","tg":"Тема"},{"id":"mon8-lit-iliad-fc-2","f":"@@l@@ е @@23@@ @@3n@@?","b":"Епитет, устойчиво свързан с определен @@4g@@ или предмет, @@w@@ се повтаря: „бързоногият Ахил“.","tg":"@@u@@"},{"id":"mon8-lit-iliad-fc-3","f":"@@l@@ е @@5m@@ @@t@@?","b":"Разгърнато, подробно @@t@@, често с @@2s@@ от @@1p@@; забавя @@1q@@ и прави събитието величаво.","tg":"@@u@@"},{"id":"mon8-lit-iliad-fc-4","f":"@@l@@ се случва в песен VI?","b":"Срещата на @@13@@ с @@24@@ и сина му — изборът @@41@@ @@y@@ и @@3x@@ към Троя.","tg":"Откъс"},{"id":"mon8-lit-iliad-fc-5","f":"Защо Ахил връща @@5i@@ на @@13@@?","b":"Молбата на Приам му напомня за собствения му баща — гневът @@3y@@ пред състраданието.","tg":"Откъс"},{"id":"mon8-lit-iliad-fc-6","f":"@@l@@ е епос?","b":"Литературен род, @@w@@ @@25@@ за събития и @@3e@@; @@1q@@ е от разказвач.","tg":"@@u@@"}],"q":[{"id":1,"qu":"@@2b@@ е централната тема на „@@2k@@“?","op":["Хитростта на Одисей","Отвличането на Елена","Падането на Троя","Гневът на Ахил"],"ci":3,"ex":"Централната тема на „Илиада“ е гневът на Ахил — с него започва поемата и той движи действието. Хитростта на Одисей е в „Одисея“, а отвличането на Елена и падането на Троя не са разказани в „Илиада“."},{"id":2,"qu":"Кой @@2e@@ @@13@@?","op":["Патрокъл","Аякс","Ахил","Диомед"],"ci":2,"ex":"Ахил @@2e@@ @@13@@ в двубой, за да @@42@@ за Патрокъл (песен XXII)."},{"id":3,"qu":"„Бързоногият Ахил“ е пример за:","op":["епическо сравнение","постоянен епитет","олицетворение","метафора"],"ci":1,"ex":"„Бързоногият Ахил“ е постоянен епитет — устойчиво определение, което се повтаря винаги с името на героя. Епическото сравнение е разгърнато сравнение, а олицетворението приписва човешки качества на неживото."},{"id":4,"qu":"@@l@@ @@3w@@ срещата на @@13@@ и @@24@@?","op":["Избора между любовта към семейството и дълга към родината","Страха на Хектор от Ахил и желанието му да избяга от боя","Упреците на Андромаха, че Хектор не обича сина си","Решението на Хектор да сключи мир с ахейците"],"ci":0,"ex":"Срещата на Хектор и Андромаха показва избора между любовта към семейството и дълга към родината — той обича жена си и сина си, но избира да защити Троя. Хектор не бяга от боя и не търси мир."},{"id":5,"qu":"С @@2t@@ @@5n@@ „@@2k@@“?","op":["С падането на Троя","С Троянския кон","Със смъртта на Ахил","С погребението на Хектор"],"ci":3,"ex":"„Илиада“ завършва с погребението на Хектор, след като Ахил връща тялото му на Приам. Смъртта на Ахил, Троянският кон и падането на Троя остават извън поемата."},{"id":6,"qu":"@@l@@ е функцията на епическото @@t@@?","op":["Да ускори действието и да съкрати описанията на битките","Да покаже чувствата на автора към героите","Да забави разказа и да направи събитието величаво и нагледно","Да предаде точно думите на героите в диалога"],"ci":2,"ex":"Епическото сравнение забавя разказа и прави събитието величаво и нагледно чрез разгърнат образ. То не ускорява действието и не предава думите на героите."}],"qq":["Защо песен XXIV е важна за @@4d@@?","Как се различават @@3n@@ и @@23@@ @@3n@@?","Какви ценности има в „@@2k@@“?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-sappho","m":["8-lit:I.3"],"t":"„Любов“ (Сафо): @@1u@@ като израз на @@1k@@","o":"Лирика — @@1z@@ род, @@w@@ @@5p@@ чувства, @@4j@@ и @@4k@@ на @@1a@@ @@s@@. Сафо (VII–VI в. пр. Хр.), остров @@5q@@.","su":{"ov":"Сафо е старогръцка поетеса от остров @@5q@@ (VII–VI в. пр. Хр.). Още в древността е смятана за една от най-големите @@19@@ поетеси. От творчеството ѝ са запазени предимно откъси. Стихотворението „Любов“ е пример за @@1x@@ — род, в @@w@@ на преден план са чувствата и преживяванията, а не @@4l@@.","kp":["Лириката @@5p@@ чувства, настроения и @@4j@@. Няма развит сюжет. Говори @@31@@ @@s@@ (@@31@@ Аз), обикновено в първо лице. Текстът е кратък, ритмичен и образен.","Названието „@@1x@@“ идва от лирата — в Древна Гърция @@32@@ са се изпълнявали с музика.","В любовната @@1x@@ на Сафо @@1j@@ е силно, почти непреодолимо @@1k@@, което обзема целия @@52@@. Преживяването се @@3w@@ чрез състоянието на @@1a@@ Аз, а не се назовава отвлечено.","При тълкуване: кой @@5r@@ и към кого; @@2t@@ е @@33@@; чрез какви образи и средства е изразено; @@2t@@ е въздействието върху @@5s@@.","@@1r@@ в културноисторически план: Сафо е от първите поети, в чиито стихове личното @@1k@@ на отделния @@52@@ става тема на @@1w@@. Това е важна стъпка в @@12@@ @@1x@@."],"eg":"В анализ на @@1x@@ не преразказвай — няма @@2t@@ да се преразкаже. Опиши @@33@@, покажи как е изразено (образи, средства, ритъм) и кажи @@2t@@ @@55@@ има.","ct":["Лирическият @@s@@ не е задължително самият автор — той е @@56@@ @@2s@@, макар при Сафо изповедността да е силна.","Лирическото @@n@@ не е епос в мерена реч: в @@1u@@ @@33@@ е на преден план, а @@4l@@ (ако ги има) са само повод."],"fd":[{"l":"Сафо","v":"VII–VI в. пр. Хр., о. @@5q@@"},{"l":"Лирика","v":"@@1z@@ род — чувства, @@4j@@, @@4k@@"},{"l":"@@6@@","v":"гласът, @@w@@ @@5r@@ в @@z@@ („@@19@@ Аз“)"},{"l":"Произход на думата","v":"от лира — музикален инструмент"}]},"nc":[{"id":"mon8-lit-sappho-chk-1","r":"Родовите @@3f@@ на @@1u@@","wn":"@@3l@@ изисква да ги разпознаваш в „Любов“.","e6":true,"sn":"Чувство на преден план; @@19@@ @@s@@; няма развит сюжет; кратък обем; ритъм; образност."},{"id":"mon8-lit-sappho-chk-2","r":"План за анализ на лирическо @@n@@","wn":"Използва се за всяка лирическа @@3m@@ до 12. клас.","e6":false,"sn":"Кой @@5r@@ → @@2t@@ @@1k@@ → какви образи и средства → @@2t@@ @@55@@."}],"fc":[{"id":"mon8-lit-sappho-fc-1","f":"@@l@@ е @@1x@@?","b":"Литературен род, @@w@@ @@5p@@ чувства, @@4j@@ и @@4k@@ на @@1a@@ @@s@@.","tg":"@@u@@"},{"id":"mon8-lit-sappho-fc-2","f":"Откъде е Сафо?","b":"От остров @@5q@@, VII–VI в. пр. Хр.","tg":"Автор"},{"id":"mon8-lit-sappho-fc-3","f":"От коя дума идва „@@1x@@“?","b":"От „лира“ — @@32@@ в Древна Гърция са се изпълнявали с музика.","tg":"@@u@@"},{"id":"mon8-lit-sappho-fc-4","f":"@@7@@","b":"Гласът, @@w@@ @@5r@@ в @@z@@; @@56@@ @@2s@@, а не непременно авторът.","tg":"@@u@@"},{"id":"mon8-lit-sappho-fc-5","f":"Как се представя @@1j@@ в @@1u@@ на Сафо?","b":"Като силно @@1k@@, което обзема целия @@52@@ и се @@3w@@ чрез състоянието на @@1a@@ Аз.","tg":"@@1r@@"},{"id":"mon8-lit-sappho-fc-6","f":"@@8@@","b":"В @@1u@@ на преден план е @@33@@, а в епоса — @@4l@@ и @@1y@@.","tg":"Сравнение"}],"q":[{"id":1,"qu":"@@l@@ е на преден план в @@1u@@?","op":["Сюжетът и действието","Диалогът между героите","Точното описание на събития","Чувствата и преживяванията"],"ci":3,"ex":"В лириката на преден план са чувствата и преживяванията на лирическия говорител. Сюжетът и действието са белег на епоса, а диалогът между героите — на драмата."},{"id":2,"qu":"Откъде е Сафо?","op":["От остров Крит","От Атина","От остров Лесбос","От Спарта"],"ci":2,"ex":"Сафо е живяла на остров Лесбос в края на VII и началото на VI в. пр. Хр. Крит, Атина и Спарта не са свързани с нея."},{"id":3,"qu":"Кое НЕ е родова характеристика на @@1u@@?","op":["Лирически говорител","Развит сюжет с много герои","Изразяване на чувство","Ритмичност и звучност"],"ci":1,"ex":"Развитият сюжет с много герои е белег на епоса, не на лириката. Лирическият говорител, изразяването на чувство и ритмичността са типични за лириката."},{"id":4,"qu":"@@l@@ е @@31@@ @@s@@?","op":["Художественият глас, който говори в стихотворението","Самият автор, който разказва за собствения си живот","Героят, за когото се разказва в стихотворението","Читателят, към когото е отправена творбата"],"ci":0,"ex":"Лирическият говорител е художественият глас, който говори в стихотворението — художествен образ. Той не е непременно самият автор, нито героят, за когото се разказва, нито читателят."},{"id":5,"qu":"Защо Сафо е важна за @@12@@ @@1x@@?","op":["Защото създава първия епос за любовта","Защото въвежда драмата в Древна Гърция","Защото пише химни само за боговете","Защото личното чувство става тема на поезията ѝ"],"ci":3,"ex":"Сафо е важна, защото в поезията ѝ личното, интимно чувство става основна тема. Тя не пише епос и драма, а химните ѝ не са единствено за боговете."},{"id":6,"qu":"Кое е най-добро начало на анализ на лирическо @@n@@?","op":["Подробен преразказ на събитията в стихотворението","Биография на автора без връзка с текста","Описание на чувството и начина, по който е изразено","Изброяване на всички художествени средства подред"],"ci":2,"ex":"Анализът на лирика започва от чувството и начина, по който то е изразено. Преразказът е подходящ за епос, биографията без текст не е анализ, а изброяването на средствата без смисъл е механично."}],"qq":["Как да анализирам лирическо @@n@@?","@@7@@","@@8@@"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-antigone","m":["8-lit:I.4"],"t":"„@@i@@“ (Софокъл): @@5u@@, @@3p@@ @@q@@ и катарзис","o":"@@i@@ @@5v@@ брат си @@35@@ въпреки забраната на @@16@@. Конфликт: божествените (неписани) закони срещу закона на владетеля. Катарзис — @@58@@ чрез страх и @@1i@@.","su":{"ov":"„@@i@@“ е @@5u@@ на Софокъл (V в. пр. Хр.), един от тримата велики трагици на Атина. Действието е в Тива. Братята Етеокъл и @@35@@ се избиват в битка за града. Новият владетел @@16@@ заповядва Етеокъл да бъде погребан с почести, а @@5i@@ на @@35@@, нападнал Тива, да остане непогребано. @@i@@, тяхната сестра, нарушава заповедта и @@5v@@ брат си.","kp":["Драма е литературният род, предназначен за сцената: @@3o@@ се развива чрез репликите на @@1y@@, без разказвач. Трагедията е @@3q@@ жанр с непримирим @@q@@ и тежък, често гибелен край за героя.","Трагическият @@q@@ е @@41@@ @@i@@ и @@16@@. Тя следва неписаните божествени закони и @@3x@@ към @@y@@ — мъртвите трябва да бъдат погребани. Той следва закона на държавата и собствената си власт. Никой не @@3y@@.","Развитие на сюжета: Исмена отказва да помогне на сестра си. @@i@@ е хваната и @@15@@ постъпката си пред @@16@@, @@w@@ я осъжда да бъде зазидана в пещера. Синът на @@16@@ Хемон, годеник на @@i@@, напразно моли баща си. Прорицателят Тирезий @@43@@ @@16@@ за гнева на @@1v@@.","@@36@@: @@16@@ @@3y@@ твърде късно. @@i@@ се е обесила, Хемон се самоубива, а след него и Евридика, @@4h@@ на @@16@@. @@16@@ остава сам и съсипан.","Трагическият @@4g@@ влиза в @@q@@, от @@w@@ няма изход, и остава верен на себе си до край. Катарзисът (по @@4m@@) е пречистването на зрителя чрез преживените страх и @@1i@@."],"eg":"Не свеждай @@4n@@ до „добра @@i@@ – лош @@16@@“. И двамата защитават ценност: тя — човешкия и божествения дълг, той — реда в държавата. Трагедията е в сблъсъка на две правоти и в гордостта, която не @@3y@@.","ct":["@@i@@ не е наказана за предателство: тя постъпва по съвест, като знае, че ще плати с @@2v@@ си.","@@16@@ също е трагичен @@4g@@: той губи сина си и @@4h@@ си и разбира грешката си, когато е твърде късно."],"fd":[{"l":"Автор","v":"Софокъл, V в. пр. Хр., Атина"},{"l":"Трагедия","v":"@@3q@@ жанр с непримирим @@q@@ и тежък край"},{"l":"Трагически @@q@@","v":"неписаните божествени закони ↔ законът на владетеля"},{"l":"Катарзис","v":"@@58@@ чрез страх и @@1i@@ (@@4m@@)"}]},"nc":[{"id":"mon8-lit-antigone-chk-1","r":"Схема на @@4n@@: @@i@@ ↔ @@16@@, ценност на всеки","wn":"Обясняването на сюжета чрез @@4n@@ е @@30@@ @@27@@.","e6":true,"sn":"@@i@@ — божествен закон, семейство, съвест. @@16@@ — държавен закон, власт, ред."},{"id":"mon8-lit-antigone-chk-2","r":"@@54@@: драма, @@5u@@, @@3p@@ @@q@@, @@3p@@ @@4g@@, катарзис","wn":"@@5@@","e6":true,"sn":"Всяко понятие + как се проявява в „@@i@@“."}],"fc":[{"id":"mon8-lit-antigone-fc-1","f":"Защо @@i@@ @@5v@@ @@35@@?","b":"@@1b@@ @@4o@@ неписаните божествени закони и @@3x@@ към @@y@@ мъртвите трябва да бъдат погребани.","tg":"Мотивация"},{"id":"mon8-lit-antigone-fc-2","f":"@@l@@ е @@3p@@ @@q@@?","b":"Непримирим сблъсък на ценности или воли, от @@w@@ няма изход без загуба.","tg":"@@u@@"},{"id":"mon8-lit-antigone-fc-3","f":"@@9@@","b":"Пречистване на зрителя чрез страх и @@1i@@ — понятие на @@4m@@.","tg":"@@u@@"},{"id":"mon8-lit-antigone-fc-4","f":"Кой е Хемон?","b":"Синът на @@16@@ и годеник на @@i@@.","tg":"Герои"},{"id":"mon8-lit-antigone-fc-5","f":"@@l@@ @@43@@ Тирезий?","b":"Че @@1v@@ са разгневени от решението на @@16@@ и го очаква нещастие.","tg":"@@2m@@"},{"id":"mon8-lit-antigone-fc-6","f":"Как @@5n@@ @@1c@@ за @@16@@?","b":"Губи @@i@@, сина си Хемон и @@4h@@ си Евридика и остава сам и съсипан.","tg":"@@36@@"}],"q":[{"id":1,"qu":"@@2b@@ заповед нарушава @@i@@?","op":["Да не погребва тялото на Етеокъл","Да не погребва тялото на Полиник","Да не напуска двореца на Креон","Да не се среща с Хемон"],"ci":1,"ex":"Креон забранява да се погребва тялото на Полиник, който е нападнал Тива, и Антигона нарушава заповедта. Етеокъл, защитникът на града, е погребан с почести."},{"id":2,"qu":"Кой е в основата на трагическия @@q@@?","op":["Антигона и Креон","Антигона и Исмена","Креон и Хемон","Креон и Тирезий"],"ci":0,"ex":"Сблъсъкът е @@41@@ @@i@@ (божествен закон) и @@16@@ (държавен закон)."},{"id":3,"qu":"@@9@@","op":["Трагичната вина на героя","Обратът в съдбата на героя","Песента на хора между епизодите","Пречистване чрез страх и състрадание"],"ci":3,"ex":"Катарзисът е пречистването на зрителя чрез страх и състрадание, които трагедията поражда (по Аристотел). Трагичната вина, обратът (перипетия) и песента на хора са други понятия."},{"id":4,"qu":"Към кой @@1z@@ род е @@1c@@?","op":["Лирика","Епос","Драма","Лироепос"],"ci":2,"ex":"Трагедията е драматичен жанр — тя е предназначена за сцената и се изгражда чрез диалог и действие. Лириката изразява чувства, а епосът разказва."},{"id":5,"qu":"Кой моли @@16@@ да пощади @@i@@?","op":["стражът","Хемон","Етеокъл","Полиник"],"ci":1,"ex":"Хемон, синът на @@16@@ и годеник на @@i@@, напразно моли баща си."},{"id":6,"qu":"Защо и @@16@@ може да се смята за трагичен @@4g@@?","op":["Защото губи сина и съпругата си и осъзнава грешката твърде късно","Защото печели спора с Антигона, но губи властта си","Защото е невинен и страда без никаква причина","Защото до края остава убеден в правотата си"],"ci":0,"ex":"Креон също е трагичен герой: неотстъпчивостта му води до гибелта на сина му Хемон и на съпругата му, а той осъзнава грешката твърде късно. Той не е невинен и не остава убеден в правотата си до края."}],"qq":["Какъв е трагическият @@q@@ в „@@i@@“?","@@2b@@ е мотивацията на @@i@@?","@@9@@"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-bible","m":["8-lit:II.1"],"t":"@@44@@. @@45@@: @@17@@, Каин и Авел, @@2l@@, Исус и Богородица","o":"Библия — Стар @@2g@@ (преди Христос) и Нов @@2g@@ (за Христос и апостолите). Стар @@2g@@: @@4p@@, @@17@@, Каин и Авел, @@2l@@. Нов @@2g@@: @@5o@@ @@4q@@ — от Матей, Марко, Лука и Йоан.","su":{"ov":"@@v@@ е епохата @@41@@ края на @@2u@@ (V в.) и @@4r@@. Нейният светоглед е християнски: в @@10@@ е Бог, а земният @@3g@@ е път към спасението на душата. @@45@@ е свещената книга на @@3h@@ и основа на @@12@@ @@51@@. Сюжетите ѝ присъстват в литературата, живописта, музиката и езика.","kp":["Структура: Старият @@2g@@ включва книгите отпреди Христос (Битие, Изход, Псалтир и др.). Новият @@2g@@ включва @@5o@@ @@4q@@ (от Матей, Марко, Лука и Йоан), Деяния на апостолите, посланията и Откровение (Апокалипсис).","Грехопадението (Битие): Бог забранява на Адам и Ева да ядат от дървото за познание на доброто и злото. Изкушени от змията, те нарушават забраната и са изгонени от рая. Сюжетът е за свободата, изкушението и отговорността.","Каин и Авел (Битие): синовете на Адам и Ева принасят дарове на Бог. Бог приема дара на Авел, а Каин от завист @@2e@@ брат си. Това е първото братоубийство — символ на завистта и греха срещу ближния. Изразът „Каинов печат“ @@2n@@ знак на престъпник.","@@2l@@ (Изход): спасен като бебе в кошница по Нил, той извежда израилтяните от робството в Египет. На планината Синай @@5k@@ от Бог десетте заповеди — основа на християнския морал.","Новият @@2g@@: Исус проповядва любов към ближния и прошка (Проповедта на планината в @@37@@ от Матей). Разпнат е и възкръсва. @@37@@ от Йоан започва с думите за Словото, което е било в началото. Богородица е @@2s@@ на майчината любов, смирението и скръбта."],"eg":"Библейският сюжет се тълкува чрез @@4d@@, която носи: @@17@@ — изкушението и отговорността; Каин и Авел — завистта; @@2l@@ — освобождението и закона; Исус — @@1j@@ и саможертвата.","ct":["@@5w@@ за блудния син е в @@37@@ от Лука, а не от Матей — внимавай при въпроси за конкретното евангелие.","@@v@@ не е просто „тъмна епоха“: тогава се създават азбуки, книжовни школи, катедрали и голяма част от @@12@@ книжнина."],"fd":[{"l":"@@44@@","v":"ок. V – XV в."},{"l":"Стар @@2g@@","v":"Битие (сътворение, грехопадение, Каин и Авел), Изход (@@2l@@)"},{"l":"Нов @@2g@@","v":"@@4q@@ от Матей, Марко, Лука, Йоан; Деяния; послания; Откровение"},{"l":"В @@1w@@","v":"Микеланджело — „Сътворението на Адам“, „Пиета“, „@@2l@@“; Леонардо — „Тайната вечеря“"}]},"nc":[{"id":"mon8-lit-bible-chk-1","r":"Таблица с библейските сюжети: книга, @@40@@, идея","wn":"@@3l@@ изисква да познаваш изброените сюжети.","e6":true,"sn":"Грехопадение, Каин и Авел, @@2l@@, Исус, Богородица — по 2 изречения и идея."},{"id":"mon8-lit-bible-chk-2","r":"Три произведения на @@1w@@ по библейски сюжети","wn":"Изследователската задача е свързана с интерпретациите в европейското изкуство.","e6":false,"sn":"Творба → автор → сюжет → @@2t@@ подчертава."}],"fc":[{"id":"mon8-lit-bible-fc-1","f":"Кои са двете основни части на @@45@@?","b":"Старият @@2g@@ и Новият @@2g@@.","tg":"Структура"},{"id":"mon8-lit-bible-fc-2","f":"Кои са @@5o@@ @@4q@@?","b":"От Матей, от Марко, от Лука и от Йоан.","tg":"Структура"},{"id":"mon8-lit-bible-fc-3","f":"Защо Каин @@2e@@ Авел?","b":"От завист, защото Бог приема дара на Авел, а неговия — не.","tg":"@@2m@@"},{"id":"mon8-lit-bible-fc-4","f":"@@l@@ @@5k@@ @@2l@@ на планината Синай?","b":"Десетте Божи заповеди.","tg":"@@2m@@"},{"id":"mon8-lit-bible-fc-5","f":"@@l@@ е @@17@@?","b":"Нарушаването на Божията забрана от Адам и Ева, след което са изгонени от рая.","tg":"@@2m@@"},{"id":"mon8-lit-bible-fc-6","f":"Коя е @@2z@@ светогледна идея на @@v@@?","b":"Теоцентризмът — Бог е в @@10@@ на света, а земният @@3g@@ е път към спасението на душата.","tg":"Епоха"}],"q":[{"id":1,"qu":"В коя част на @@45@@ е историята за Каин и Авел?","op":["В Стария завет","В Новия завет","В Евангелието от Матей","В Деянията на апостолите"],"ci":0,"ex":"Историята за Каин и Авел е в книгата Битие от Стария завет. Новият завет, включително евангелията и Деянията, разказва за Исус и апостолите."},{"id":2,"qu":"Кой извежда израилтяните от Египет?","op":["Авраам","Мойсей","Ной","Давид"],"ci":1,"ex":"Мойсей извежда израилтяните от египетското робство. Авраам е праотецът, Ной спасява живота от потопа, а Давид е цар на Израил."},{"id":3,"qu":"@@2b@@ е @@2z@@ идея на сюжета за Каин и Авел?","op":["Непокорството пред Бога и изгонването от рая","Вярата, подложена на тежко изпитание","Завистта и грехът срещу ближния","Прошката и помирението между братята"],"ci":2,"ex":"Сюжетът за Каин и Авел е за завистта и греха срещу ближния — Каин убива брат си от завист. Непокорството и изгонването от рая са в историята за Адам и Ева."},{"id":4,"qu":"Колко са евангелията в Новия @@2g@@?","op":["Три","Пет","Дванадесет","Четири"],"ci":3,"ex":"В Новия завет има четири евангелия — от Матей, Марко, Лука и Йоан. Дванадесет са апостолите, а не евангелията."},{"id":5,"qu":"Кое произведение е по библейски сюжет?","op":["„Тайната вечеря“ на Леонардо","„Мона Лиза“ на Леонардо","„Раждането на Венера“ на Ботичели","„Атинската школа“ на Рафаело"],"ci":0,"ex":"Стенописът изобразява последната вечеря на Исус с апостолите."},{"id":6,"qu":"Какъв е светогледът на @@v@@?","op":["Антропоцентричен — човекът е в центъра","Теоцентричен — Бог е в центъра","Рационалистичен — разумът е в центъра","Митологичен — олимпийските богове са в центъра"],"ci":1,"ex":"Средновековният светоглед е теоцентричен — Бог е в центъра. Антропоцентризмът е белег на Ренесанса, рационализмът — на Просвещението, а олимпийските богове — на Античността."}],"qq":["@@2b@@ е структурата на @@45@@?","@@2b@@ идея носи @@17@@?","Кои творби на @@1w@@ са по библейски сюжети?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-life-of-constantine","m":["8-lit:II.2"],"t":"„Пространно житие на @@h@@ – @@20@@“: агиография, житие, символ","o":"Житие — @@4b@@ за @@2v@@ на светец. @@h@@-@@20@@ @@59@@: роден в Солун, сънят за @@28@@ (@@4z@@), споровете, Моравската мисия, спорът във @@5a@@, @@46@@ в Рим (869).","su":{"ov":"„Пространно житие на @@h@@ – @@20@@“ е старобългарска @@3m@@, писана скоро след @@46@@ на @@38@@ (869). Авторството ѝ традиционно се свързва с кръга на учениците — най-често с Климент Охридски. Житието @@25@@ @@2v@@ на създателя на @@1l@@ @@4s@@ и @@15@@ правото на славяните да славят Бог на своя език.","kp":["Агиография е литературата за светците: жития, похвални слова, служби. Пространното житие @@25@@ подробно целия @@3g@@ на @@38@@ — раждането, детството с белезите на избраност, подвизите, @@46@@ — с цел прослава и поука.","Детство и образование: роден в Солун, седмото дете в @@y@@. Като седемгодишен сънува, че @@4f@@ за невеста @@28@@ — @@4z@@. Учи в Цариград и заради учеността си е наречен @@59@@.","Подвизи: спорове с иконоборци, сарацини (араби) и хазари в защита на @@3h@@. По молба на моравския княз Ростислав, заедно с брат си Методий @@34@@ @@1l@@ @@4s@@ (глаголицата) и превежда богослужебните книги.","Спорът във @@5a@@ с @@29@@, които твърдят, че Бог може да се слави само на еврейски, @@4t@@ и @@47@@. @@h@@ им @@5x@@, че дъждът и слънцето са дадени еднакво на всички, и цитира Писанието. Папата в Рим одобрява @@m@@ книги. @@h@@ приема монашеското име @@20@@ и умира в Рим през 869 г.","Символи: @@28@@ (@@4z@@) — избраността и посвещението на знанието; светлината и книгата — просвещението. В съпоставка с „Азбучна молитва“ на @@h@@ @@3r@@ се вижда средновековната идея, че @@18@@ и книгата са дар от Бога и път към спасението."],"eg":"Тълкувай житието чрез жанра му: всяка подробност от @@2v@@ на @@h@@ е подбрана, за да го покаже като избран от Бога и да оправдае делото му — @@1l@@ @@4s@@.","ct":["Житието не е обективна биография в днешния смисъл: целта му е да прослави @@38@@ и да поучи @@5s@@.","„Азбучна молитва“ не е от @@h@@-@@20@@, а от @@h@@ @@3r@@; тя е акростих — началните @@x@@ на @@32@@ следват азбуката."],"fd":[{"l":"Агиография","v":"литература за @@2v@@ на светците"},{"l":"Пространно житие","v":"подробен @@4b@@ за целия @@3g@@ на @@38@@"},{"l":"Смърт на @@h@@-@@20@@","v":"14 февруари 869 г., Рим"},{"l":"Символ","v":"@@1@@"},{"l":"Акростих","v":"началните @@x@@ на @@32@@ образуват дума или @@4s@@"}]},"nc":[{"id":"mon8-lit-life-chk-1","r":"Хронология на @@2v@@ на @@h@@-@@20@@ по житието","wn":"@@3l@@ изисква да познаваш съдържанието на @@14@@.","e6":true,"sn":"Солун → сънят за @@4z@@ → Цариград → споровете → Моравия → @@5a@@ → Рим, 869."},{"id":"mon8-lit-life-chk-2","r":"Жанрови @@5y@@ на пространното житие с примери","wn":"@@3i@@ на @@4u@@ @@3f@@ е @@30@@ @@27@@.","e6":true,"sn":"Целият @@3g@@; @@5y@@ на избраност; подвизи; смърт; прослава и поука."}],"fc":[{"id":"mon8-lit-life-fc-1","f":"@@l@@ е агиография?","b":"Литература за @@2v@@ на светците — жития, похвални слова и др.","tg":"@@u@@"},{"id":"mon8-lit-life-fc-2","f":"@@l@@ @@4f@@ @@h@@ в съня си като дете?","b":"@@28@@ — @@4z@@ — за своя невеста.","tg":"@@2m@@"},{"id":"mon8-lit-life-fc-3","f":"Кои са @@29@@?","b":"Онези, които твърдят, че Бог може да се слави само на еврейски, @@4t@@ и @@47@@.","tg":"@@2m@@"},{"id":"mon8-lit-life-fc-4","f":"По чия молба братята заминават за Моравия?","b":"По молба на моравския княз Ростислав.","tg":"@@2m@@"},{"id":"mon8-lit-life-fc-5","f":"Къде и кога умира @@h@@-@@20@@?","b":"В Рим, на 14 февруари 869 г.","tg":"Факт"},{"id":"mon8-lit-life-fc-6","f":"@@l@@ е символ?","b":"Художествен @@1@@та и избраността.","tg":"@@u@@"}],"q":[{"id":1,"qu":"@@l@@ е пространно житие?","op":["Кратък разказ за светец, четен при богослужение","Подробен разказ за целия живот на светец","Похвално слово за чудесата на светец","Летопис за делата на владетелите"],"ci":1,"ex":"Пространното житие @@25@@ целия @@3g@@ на @@38@@ с цел прослава."},{"id":2,"qu":"Къде се ражда @@h@@-@@20@@?","op":["В Солун","В Константинопол","В Охрид","В Преслав"],"ci":0,"ex":"Според житието Константин-Кирил се ражда в Солун. Константинопол е мястото на обучението му, а Охрид и Преслав са по-късни книжовни центрове."},{"id":3,"qu":"@@l@@ @@50@@ @@4z@@ в съня на @@h@@?","op":["Красотата и земната любов","Богатството и властта","Монашеството и отказа от света","Мъдростта и посвещението на знанието"],"ci":3,"ex":"В съня на Константин София символизира мъдростта (на гръцки „софия“) и посвещението му на знанието. Той я избира пред красотата и богатството."},{"id":4,"qu":"С кого спори @@h@@ във @@5a@@?","op":["С иконоборците","С хазарите","С триезичниците","С агаряните (арабите)"],"ci":2,"ex":"Във @@5a@@ той @@15@@ @@m@@ книги срещу @@29@@."},{"id":5,"qu":"Кой е авторът на „Азбучна молитва“?","op":["Константин-Кирил","Константин Преславски","Климент Охридски","Черноризец Храбър"],"ci":1,"ex":"„Азбучна молитва“ е на Константин Преславски — всеки стих започва с поредната буква от азбуката. Черноризец Храбър е автор на „За буквите“."},{"id":6,"qu":"@@2b@@ е @@2z@@ цел на житието?","op":["Да прослави светеца и да поучи читателя","Да разкаже точна и пълна биография","Да опише историята на държавата","Да забавлява със случки от живота"],"ci":0,"ex":"Целта на житието е да прослави светеца и да даде пример за подражание. То не е точна биография, история на държавата или забавен разказ."}],"qq":["Кои са @@4u@@ @@5y@@ на житието?","@@l@@ @@50@@ @@4z@@?","Как @@h@@ @@15@@ @@m@@ книги?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-on-the-letters","m":["8-lit:II.3"],"t":"„За @@18@@“ (@@3k@@ @@1o@@): @@39@@ @@48@@ и @@1m@@","o":"Защита на @@m@@ @@x@@: преди — „черти и резки“, после — @@4t@@ и @@47@@ @@x@@ „без @@4v@@“. @@h@@ @@34@@ 38 @@x@@. Гръцките @@x@@ са @@1s@@ от @@3v@@ хора за дълго @@3z@@, @@m@@ — от един свят мъж за кратко.","su":{"ov":"„За @@18@@“ е старобългарска @@3m@@ от края на IX или началото на X в. Авторът се подписва като @@3k@@ @@1o@@ („черноризец“ значи монах). @@26@@ @@15@@ @@1l@@ @@4s@@ от онези, които смятат, че тя е по-нисша от гръцката. Тя е едновременно @@39@@ @@48@@ (спор с опоненти) и @@1m@@ (защита на кауза).","kp":["Полемичното @@48@@ е @@3m@@, в която авторът спори с чужди възгледи и ги опровергава с доводи. Апологията е защита — на учение, кауза или личност. „За @@18@@“ спори с противниците на @@1l@@ писменост и @@15@@ @@18@@ и техния създател.","Историята на писмеността @@4o@@ @@1o@@: отначало славяните нямат книги и си служат с „черти и резки“. След покръстването пишат с @@4t@@ и @@47@@ @@x@@, но „без @@4v@@“ — те не предават добре @@m@@ звукове. Тогава Бог изпраща @@h@@ @@59@@, наречен @@20@@, @@w@@ @@34@@ 38 @@x@@: едни по образеца на @@1n@@, а други @@4o@@ @@1l@@ реч.","Основни доводи: @@1n@@ @@x@@ са @@1s@@ от @@3v@@ хора за дълго @@3z@@ и при това от езичници. @@5b@@ са @@1s@@ от един свят мъж за няколко години. Ако попиташ @@1n@@ книжовници кой е създал @@18@@ им, малцина ще знаят. Ако попиташ @@m@@ „азбукарчета“, всички ще кажат: @@h@@ @@59@@, наречен @@20@@.","@@26@@ посочва и годината на създаване на @@18@@ — 6363 г. от @@4p@@ на света (855 г.) — и владетелите по онова @@3z@@.","Начини на @@55@@: реторични въпроси, @@t@@ и противопоставяне (@@4t@@ – славянски @@x@@), логическа последователност на доводите, позоваване на авторитета на Писанието. В края тонът става тържествен."],"eg":"За есе или анализ подреди доводите на @@1o@@ в схема „твърдение на противника → @@49@@ на @@1o@@“. Така се вижда полемичният характер на @@14@@.","ct":["@@3k@@ @@1o@@ не е създател на азбуката — той я @@15@@. Създателят е @@h@@-@@20@@.","Числото 38 е броят на @@18@@, @@1s@@ от @@h@@, а не броят на @@1n@@ @@x@@ (те са 24)."],"fd":[{"l":"Време","v":"края на IX – началото на X в."},{"l":"Полемично @@48@@","v":"спор с чужди възгледи и опровергаването им"},{"l":"Апология","v":"защита на кауза, учение или личност"},{"l":"Брой @@x@@","v":"38 славянски @@x@@ (@@1n@@ са 24)"},{"l":"Година по @@14@@","v":"6363 г. от @@4p@@ на света = 855 г."}]},"nc":[{"id":"mon8-lit-letters-chk-1","r":"Таблица „довод на противника → @@49@@ на @@1o@@“","wn":"Показва @@4u@@ @@5y@@ на полемичното @@48@@.","e6":true,"sn":"@@5b@@ @@x@@ са нови → и @@1n@@ някога са били нови. Създадени от един @@52@@ → от свят мъж, за кратко @@3z@@."},{"id":"mon8-lit-letters-chk-2","r":"@@54@@: @@39@@ @@48@@, @@1m@@","wn":"Двете понятия са нови по @@3j@@.","e6":true,"sn":"Полемично @@48@@ — спор; @@1m@@ — защита."}],"fc":[{"id":"mon8-lit-letters-fc-1","f":"@@l@@ е @@39@@ @@48@@?","b":"Творба, в която авторът спори с чужди възгледи и ги опровергава с доводи.","tg":"@@u@@"},{"id":"mon8-lit-letters-fc-2","f":"@@l@@ е @@1m@@?","b":"Защита на кауза, учение или личност.","tg":"@@u@@"},{"id":"mon8-lit-letters-fc-3","f":"С @@2t@@ пишат славяните преди създаването на азбуката @@4o@@ @@1o@@?","b":"С „черти и резки“, а после с @@4t@@ и @@47@@ @@x@@ „без @@4v@@“.","tg":"Съдържание"},{"id":"mon8-lit-letters-fc-4","f":"Колко @@x@@ @@34@@ @@h@@-@@20@@ @@4o@@ „За @@18@@“?","b":"38 @@x@@.","tg":"Факт"},{"id":"mon8-lit-letters-fc-5","f":"@@l@@ @@2n@@ „черноризец“?","b":"Монах — @@52@@, @@w@@ носи черно расо.","tg":"Автор"},{"id":"mon8-lit-letters-fc-6","f":"Кой е най-силният довод на @@1o@@ за @@m@@ @@x@@?","b":"Те са @@1s@@ от един свят мъж за кратко @@3z@@, а @@1n@@ — от @@3v@@ езичници за дълго @@3z@@.","tg":"Довод"}],"q":[{"id":1,"qu":"@@l@@ @@15@@ „За @@18@@“?","op":["Гръцката азбука","Славянската азбука","Латинската азбука","Триезичната догма"],"ci":1,"ex":"„За буквите“ защитава славянската азбука — творбата е апология на славянските букви. Тя спори именно с триезичната догма, според която богослужението е позволено само на гръцки, латински и еврейски."},{"id":2,"qu":"Колко @@x@@ @@34@@ @@h@@-@@20@@ @@4o@@ @@1o@@?","op":["38","24","32","36"],"ci":0,"ex":"Според Храбър Константин-Кирил създава 38 букви — част по образеца на гръцките, а други според славянската реч. 24 е броят на гръцките букви."},{"id":3,"qu":"Кой е създател на @@m@@ @@x@@ @@4o@@ @@14@@?","op":["Методий, братът на Константин","Климент Охридски","Черноризец Храбър","Константин Философ, наречен Кирил"],"ci":3,"ex":"Според творбата създател на славянските букви е Константин Философ, наречен Кирил. Методий му помага, Климент е техен ученик, а Храбър е авторът, който защитава делото им."},{"id":4,"qu":"Към кои жанрове е „За @@18@@“?","op":["Житие и похвално слово","Поучение и молитва","Полемично слово и апология","Летопис и хроника"],"ci":2,"ex":"@@26@@ спори с противниците (полемика) и @@15@@ @@18@@ (@@1m@@)."},{"id":5,"qu":"@@l@@ @@2n@@ „без @@4v@@“ за @@1n@@ и латинските @@x@@?","op":["Че са твърде много и трудни за учене","Че не предават добре славянските звукове","Че не са подредени по азбучен ред","Че са забранени от Църквата"],"ci":1,"ex":"„Без устроение“ означава, че гръцките и латинските букви не предават добре звуковете на славянския език. Това не се отнася до броя, реда или забрана от Църквата."},{"id":6,"qu":"Какъв довод @@5l@@ @@1o@@?","op":["Гръцките букви са създадени от много езичници, а славянските — от един свят мъж","Славянските букви са по-стари от гръцките и затова са по-ценни за Бога","Гръцките букви са създадени от светци, а славянските — от езичници","Славянските букви са одобрени от императора и от патриарха"],"ci":0,"ex":"Храбър противопоставя: гръцките букви са създадени от много езичници за дълго време, а славянските — от един свят мъж за кратко. Той не твърди, че славянските са по-стари."}],"qq":["Какви доводи @@5l@@ @@1o@@?","@@2b@@ е разликата @@41@@ @@39@@ @@48@@ и @@1m@@?","Как @@14@@ въздейства на @@5s@@?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-decameron","m":["8-lit:III.1"],"t":"@@5z@@. „@@1d@@“ (Дж. Бокачо): „@@5w@@ за @@4c@@ @@2o@@“ и @@2a@@","o":"@@5z@@ — възраждане на античната @@51@@, хуманизъм, @@2w@@ в @@10@@. „@@1d@@“ — 100 новели, разказани за 10 дни. Ден I, новела 3: @@2h@@, @@r@@ и @@4c@@ @@2o@@.","su":{"ov":"Ренесансът (Възраждането) е културната епоха след @@v@@ (XIV–XVI в.), започнала в Италия. Той „възражда“ античната @@51@@ и @@2f@@ в @@10@@ човека — неговия разум, таланти и право на земна радост. Това е хуманизмът. „@@1d@@“ на Джовани Бокачо (1313–1375) е сборник със 100 новели. Десет млади @@5c@@ бягат от чумата през 1348 г. и в продължение на десет дни всеки @@25@@ по една история („декамерон“ значи „десет дни“).","kp":["Светогледни идеи на @@4r@@: антропоцентризъм (@@2w@@ е в @@10@@), вяра в @@60@@ и способностите на човека, интерес към античността, утвърждаване на земния @@3g@@, свободата и личността.","@@2m@@ на @@2a@@: султан @@2h@@ има нужда от пари. Иска да хване в капан богатия евреин @@r@@ и го пита коя от @@4c@@ вери — еврейската, мюсюлманската или християнската — е @@1e@@.","@@r@@ @@5x@@ с притча. Богат @@52@@ имал скъпоценен пръстен и @@w@@ го наследи, ставал глава на рода. Един баща обичал еднакво тримата си сина и поръчал два @@2o@@, неразличими от истинския. След @@46@@ му всеки син имал пръстен и никой не можел да докаже, че неговият е истинският. Така е и с @@4c@@ вери: всеки народ смята своята за истинска, а въпросът остава без @@49@@.","@@36@@: @@2h@@ оценява мъдростта на @@r@@ и открито му @@25@@ нуждата си. @@r@@ му заема парите, @@2h@@ ги връща, награждава го богато и двамата остават приятели.","Новелата е кратък @@2p@@ жанр: едно @@40@@, малко @@3e@@, напрегнато действие и неочакван обрат. Тук обратът е, че мъдрият @@49@@ превръща капана в @@5d@@. Идеята е за верската търпимост и силата на @@60@@."],"eg":"Обърни внимание, че притчата е @@4b@@ в разказа: @@r@@ не @@5x@@ пряко, а чрез иносказание. Това е знак за ренесансовата вяра в @@60@@ и находчивостта.","ct":["Новелата не казва коя вяра е @@1e@@ — точно в това е нейната мъдрост и @@4d@@ ѝ за търпимост.","„Новела“ тук е жанр на кратката проза, а не новина или нов закон."],"fd":[{"l":"@@5z@@","v":"XIV–XVI в., начало в Италия"},{"l":"Хуманизъм","v":"@@2w@@, разумът и земният @@3g@@ са в @@10@@"},{"l":"„@@1d@@“","v":"100 новели, 10 разказвачи, 10 дни; чумата във Флоренция, 1348 г."},{"l":"Новела","v":"кратък @@2p@@ жанр с едно @@40@@ и неочакван обрат"}]},"nc":[{"id":"mon8-lit-decameron-chk-1","r":"Сюжетът в 4 стъпки и @@4d@@ на @@2a@@","wn":"@@53@@ на @@2a@@ е @@30@@ @@27@@ по @@3j@@.","e6":true,"sn":"Капан → притча → мъдър @@49@@ → @@5d@@. Идея: търпимост и разум."},{"id":"mon8-lit-decameron-chk-2","r":"Сравнение @@44@@ – @@5z@@","wn":"Различаването на светогледните идеи на епохите е @@23@@ акцент.","e6":false,"sn":"Бог в @@10@@ ↔ @@2w@@ в @@10@@; отвъдният @@3g@@ ↔ земният @@3g@@; смирение ↔ разум и личност."}],"fc":[{"id":"mon8-lit-decameron-fc-1","f":"@@l@@ е хуманизъм?","b":"Ренесансовият възглед, @@w@@ @@2f@@ в @@10@@ човека, неговия разум и достойнство.","tg":"Епоха"},{"id":"mon8-lit-decameron-fc-2","f":"@@l@@ значи „@@1d@@“?","b":"„Десет дни“ — толкова продължават разказите на десетимата млади @@5c@@.","tg":"Творба"},{"id":"mon8-lit-decameron-fc-3","f":"@@l@@ пита @@2h@@ @@r@@?","b":"Коя от @@4c@@ вери — еврейската, мюсюлманската или християнската — е @@1e@@.","tg":"@@2m@@"},{"id":"mon8-lit-decameron-fc-4","f":"@@b@@","b":"Трите вери — всяка смята себе си за истинска и никой не може да докаже обратното.","tg":"@@1r@@"},{"id":"mon8-lit-decameron-fc-5","f":"@@l@@ е новела?","b":"Кратък @@2p@@ жанр с едно @@40@@, малко @@3e@@, напрегнато действие и неочакван обрат.","tg":"@@u@@"},{"id":"mon8-lit-decameron-fc-6","f":"@@2b@@ е @@4d@@ на „@@5w@@ за @@4c@@ @@2o@@“?","b":"Търпимост @@41@@ вярите и победа на @@60@@ и мъдростта.","tg":"Идея"}],"q":[{"id":1,"qu":"@@2b@@ е @@2z@@ светогледна идея на @@4r@@?","op":["Бог и отвъдният живот са в центъра","Природата и инстинктите са в центъра","Човекът и неговият разум са в центъра","Държавата и законът са в центъра"],"ci":2,"ex":"Ренесансът поставя в центъра човека и неговия разум — светогледът е хуманистичен и антропоцентричен. Бог и отвъдният живот са в центъра на средновековния светоглед."},{"id":2,"qu":"Защо младите @@5c@@ напускат града в „@@1d@@“?","op":["Заради войната","Заради глада","Заради наводнението","Заради чумата"],"ci":3,"ex":"Рамковата история на „Декамерон“ е бягството на десет млади флорентинци от чумата през 1348 г. Войната, гладът и наводнението не са причината."},{"id":3,"qu":"Как @@5x@@ @@r@@ на въпроса на @@2h@@?","op":["С притча за трите пръстена","С притча за блудния син","Като казва, че християнството е истинската вяра","Като отказва да отговори"],"ci":0,"ex":"Мелхиседек отговаря на Саладин с притчата за трите пръстена — иносказателна история, с която избягва капана. Ако посочи една вяра за истинска, би обидил другите."},{"id":4,"qu":"@@l@@ е неочакваният обрат в @@2a@@?","op":["Саладин наказва Мелхиседек","Капанът се превръща в приятелство","Мелхиседек губи богатството си","Саладин приема еврейската вяра"],"ci":1,"ex":"@@28@@ на @@r@@ печели уважението и приятелството на @@2h@@."},{"id":5,"qu":"Колко новели има в „@@1d@@“?","op":["10","50","100","1001"],"ci":2,"ex":"„Декамерон“ съдържа 100 новели — десет разказвачи разказват по една на ден в продължение на десет дни. 1001 е броят на нощите в „Хиляда и една нощ“."},{"id":6,"qu":"@@2b@@ идея @@3s@@ @@2a@@?","op":["Превъзходството на една вяра","Ползата от хитростта за пари","Покорството пред владетеля","Търпимостта и силата на разума"],"ci":3,"ex":"@@5w@@ оставя въпроса без @@49@@ и @@3s@@ търпимостта."}],"qq":["@@b@@","Кои са белезите на @@2a@@?","С @@2t@@ Ренесансът се различава от @@v@@?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-don-quixote","m":["8-lit:III.2"],"t":"„Дон @@1g@@“ (М. де @@1t@@): @@57@@ и пародия","o":"Глава I: идалгото от Ла Манча полудява от @@2q@@ @@3a@@ и става странстващ рицар. Глава VIII: битката с вятърните @@2i@@. Пародия на рицарските @@3a@@.","su":{"ov":"„Дон @@1g@@“ на Мигел де @@1t@@ (1547–1616) е @@57@@ в две части (1605 и 1615). Той е смятан за един от първите модерни @@3a@@ в @@12@@ литература. @@1t@@ @@3u@@ рицарските @@3a@@, популярни по негово @@3z@@. Така @@34@@ дълбок @@2s@@ на идеалиста, @@w@@ живее в свой свят, различен от действителността.","kp":["Глава I: беден благородник (идалго) от Ла Манча, около петдесетгодишен, чете толкова @@3v@@ @@2q@@ @@3a@@, че губи разсъдъка си. Решава да стане странстващ рицар. Стяга старо оръжие, нарича кльощавия си кон @@61@@, а себе си — Дон @@1g@@ де ла Манча. За дама на сърцето си @@4f@@ селско момиче, което нарича @@4a@@ Тобоска.","Глава VIII: Дон @@1g@@ вижда тридесет-четиридесет вятърни @@2i@@ и ги взема за @@62@@. Оръженосецът му Санчо Панса го @@43@@, но той се хвърля в атака. Крилото на мелницата го събаря заедно с коня. Дон @@1g@@ @@5g@@ поражението си с магьосник, @@w@@ превърнал великаните в @@2i@@.","Родови и жанрови @@3f@@: епос — повествование от разказвач за събития и @@3e@@. Романът е голям @@2p@@ жанр: @@3v@@ @@3e@@ и епизоди, голям период от @@3z@@, сложен @@2s@@ на героя.","Пародия е подражание на известна @@3m@@ или жанр с цел осмиване. @@1t@@ @@5l@@ познатите елементи на рицарския @@57@@ — рицар, дама, оръженосец, подвизи — но ги @@2f@@ в обикновена, бедна действителност. Така те стават смешни.","Ценности: Дон @@1g@@ е смешен, но и @@3t@@ — вярва в справедливостта и иска да помага на слабите. Двойката Дон @@1g@@ – Санчо Панса противопоставя идеализма и практичния здрав разум."],"eg":"Не описвай Дон @@1g@@ само като луд. Покажи двойствеността му: смешен в действията си, но @@3t@@ в целите си. В тази двойственост е дълбочината на образа.","ct":["@@4a@@ не е истинска дама — тя е обикновено селско момиче, превърнато от въображението на героя в @@2q@@ идеал.","Фразеологизмът „борба с вятърни @@2i@@“ @@2n@@ борба с въображаеми противници — не просто „безсмислена работа“."],"fd":[{"l":"Автор","v":"Мигел де @@1t@@ (1547–1616)"},{"l":"Издание","v":"I част — 1605 г., II част — 1615 г."},{"l":"Роман","v":"голям @@2p@@ жанр с @@3v@@ @@3e@@ и епизоди"},{"l":"Пародия","v":"подражание на @@3m@@ или жанр с цел осмиване"}]},"nc":[{"id":"mon8-lit-quixote-chk-1","r":"Пародийни двойки: @@2q@@ @@57@@ → Дон @@1g@@","wn":"@@3i@@ на пародията е @@30@@ @@27@@.","e6":true,"sn":"Благороден рицар → беден идалго; бойният кон → кльощавият @@61@@; дама → селско момиче; @@62@@ → @@2i@@."},{"id":"mon8-lit-quixote-chk-2","r":"Сравнение Дон @@1g@@ – Санчо Панса","wn":"Помага за @@2x@@ на ценностите в @@14@@.","e6":false,"sn":"Идеализъм, въображение ↔ практичност, здрав разум."}],"fc":[{"id":"mon8-lit-quixote-fc-1","f":"Защо идалгото решава да стане рицар?","b":"@@1b@@ е прочел толкова @@3v@@ @@2q@@ @@3a@@, че е загубил разсъдъка си.","tg":"@@2m@@"},{"id":"mon8-lit-quixote-fc-2","f":"Как се казва конят на Дон @@1g@@?","b":"@@61@@.","tg":"Герои"},{"id":"mon8-lit-quixote-fc-3","f":"Кого Дон @@1g@@ @@4f@@ за дама на сърцето си?","b":"Селско момиче, което нарича @@4a@@ Тобоска.","tg":"Герои"},{"id":"mon8-lit-quixote-fc-4","f":"За @@2t@@ взема Дон @@1g@@ вятърните @@2i@@?","b":"За @@62@@.","tg":"@@2m@@"},{"id":"mon8-lit-quixote-fc-5","f":"@@l@@ е пародия?","b":"Подражание на @@3m@@ или жанр с цел осмиване.","tg":"@@u@@"},{"id":"mon8-lit-quixote-fc-6","f":"@@c@@","b":"Рицарските @@3a@@.","tg":"@@u@@"}],"q":[{"id":1,"qu":"@@c@@","op":["Античните трагедии","Рицарските романи","Средновековните жития","Лирическите сонети"],"ci":1,"ex":"„Дон Кихот“ пародира рицарските романи, които са били изключително популярни по времето на Сервантес. Трагедиите, житията и сонетите не са обект на пародията."},{"id":2,"qu":"Кой е оръженосецът на Дон @@1g@@?","op":["Санчо Панса","Росинант","Самсон Караско","Дулсинея"],"ci":0,"ex":"Оръженосецът на Дон Кихот е простият и практичен Санчо Панса. Росинант е конят на Дон Кихот, Дулсинея — неговата въображаема дама, а Самсон Караско — съсед бакалавър."},{"id":3,"qu":"@@l@@ се случва в глава VIII?","op":["Битката със стадото овце","Посвещаването в рицарство в хана","Срещата с Дулсинея","Битката с вятърните мелници"],"ci":3,"ex":"В глава VIII Дон Кихот напада вятърните мелници, които смята за великани. Битката със стадото овце и посвещаването в рицарство в хана са други епизоди."},{"id":4,"qu":"Как Дон @@1g@@ @@5g@@ поражението си?","op":["Санчо не го е предупредил навреме","Росинант се е спънал по време на атаката","Магьосник превърнал великаните в мелници","Великаните са били твърде много"],"ci":2,"ex":"Дон Кихот обяснява поражението с това, че магьосник превърнал великаните в мелници — така запазва илюзията си. Той не обвинява Санчо или Росинант."},{"id":5,"qu":"Защо „Дон @@1g@@“ е @@57@@?","op":["Защото е кратък и разказва за едно събитие","Защото има много герои, епизоди и сложен образ на героя","Защото е написан в стихове с рима","Защото е предназначен за сцената"],"ci":1,"ex":"„Дон Кихот“ е роман — голям епически жанр с много герои, епизоди и сложен образ на героя. Той не е кратък, не е в стихове и не е предназначен за сцената."},{"id":6,"qu":"Кое описва най-точно образа на Дон @@1g@@?","op":["Смешен в действията си, но благороден в целите си","Смешен в действията си и безсмислен в целите си","Хитър измамник, който се прави на рицар","Мъдър рицар, който винаги постига целите си"],"ci":0,"ex":"Дон Кихот е смешен в действията си, но благороден в целите си — защитава слабите и вярва в справедливостта. Той не е измамник, а и не постига целите си."}],"qq":["Как @@1t@@ @@3u@@ рицарския @@57@@?","Защо Дон @@1g@@ е @@3t@@?","@@l@@ е @@57@@?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-hamlet","m":["8-lit:III.3"],"t":"„@@k@@“ (У. @@2j@@): @@1c@@ на мислещия @@52@@","o":"Призракът разкрива, че @@o@@ е убил краля. @@k@@ се преструва на луд, @@2f@@ „@@21@@“, @@2e@@ @@3b@@. Финалът: двубоят с @@5e@@, @@46@@ на @@2r@@, @@o@@ и @@k@@.","su":{"ov":"„@@k@@“ е @@5u@@ на Уилям @@2j@@ (1564–1616), писана около 1600 г. Действието е в датския замък Елсинор. Принц @@k@@ научава от призрака на баща си, че кралят е бил убит от брат си @@o@@. @@o@@ е взел короната и се е оженил за кралицата @@2r@@. @@k@@ трябва да @@42@@, но се колебае. Така @@1c@@ става драма на съвестта, мисълта и избора.","kp":["Конфликт: външният е @@41@@ @@k@@ и @@o@@ — справедливостта срещу престъплението и покварата в кралството. Вътрешният е в самия @@k@@ — @@41@@ @@3x@@ да @@42@@ и съмненията му дали призракът казва @@1h@@ и дали отмъщението е справедливо.","Развитие: @@k@@ се преструва на луд. Заедно с актьори @@2f@@ пиеса за подобно убийство („@@21@@“), за да провери @@o@@ — и реакцията на краля го издава. По погрешка @@k@@ @@2e@@ @@3b@@, бащата на @@63@@ и @@5e@@, скрит зад завесата. Изпратен е в Англия, но се връща. @@63@@ обезумява и се удавя.","@@36@@: @@o@@ и @@5e@@ подготвят двубой с отровна шпага и отровно вино. @@2r@@ пие от виното и умира. @@5e@@ и @@k@@ са ранени, а @@5e@@ разкрива заговора. @@k@@ @@2e@@ @@o@@ и умира, като моли приятеля си Хорацио да разкаже @@1h@@.","Мотивация: @@k@@ не е страхливец. Той се бави, защото @@4j@@, търси доказателства и се пита за смисъла на @@2v@@ и @@46@@ („Да бъдеш или да не бъдеш“). Ренесансовият @@52@@ вече @@3c@@ сам, а не следва сляпо @@3x@@.","Ренесансови черти: интерес към вътрешния свят на личността, разумът и съмнението, проблемът за властта и морала, за @@1h@@ и лъжата."],"eg":"Когато тълкуваш колебанието на @@k@@, свържи го с @@4r@@: героят @@4j@@ и @@3c@@ морално. Затова отлага @@3o@@ — и в това е @@1c@@ му.","ct":["@@k@@ не @@2e@@ @@3b@@ нарочно — @@2e@@ го, като @@4j@@, че зад завесата е @@o@@. Това поражда нови @@5t@@: лудостта на @@63@@ и отмъщението на @@5e@@.","@@k@@ не е просто „луд“: лудостта му е преструвка, за да скрие намеренията си и да разкрие @@1h@@."],"fd":[{"l":"Автор","v":"Уилям @@2j@@ (1564–1616)"},{"l":"Създаване","v":"около 1600 г."},{"l":"Място","v":"Елсинор, Дания"},{"l":"Външен @@q@@","v":"@@k@@ ↔ @@o@@"},{"l":"Вътрешен @@q@@","v":"дълг да @@42@@ ↔ съмнение и съвест"}]},"nc":[{"id":"mon8-lit-hamlet-chk-1","r":"Схема на @@1y@@ и връзките им","wn":"Нужна е, за да обясниш мотивацията на @@1y@@.","e6":true,"sn":"@@k@@ — @@o@@ (чичо, убиец) — @@2r@@ (майка) — @@3b@@ — @@63@@ и @@5e@@ (деца на @@3b@@) — Хорацио (приятел)."},{"id":"mon8-lit-hamlet-chk-2","r":"Външният и вътрешният @@q@@ с по два примера","wn":"Обясняването на сюжета чрез трагическия @@q@@ е @@30@@ @@27@@.","e6":true,"sn":"Външен — „@@21@@“, двубоят. Вътрешен — монолозите, колебанието."}],"fc":[{"id":"mon8-lit-hamlet-fc-1","f":"@@l@@ разкрива призракът на @@k@@?","b":"Че бащата на @@k@@ е убит от брат си @@o@@.","tg":"@@2m@@"},{"id":"mon8-lit-hamlet-fc-2","f":"@@l@@ е „@@21@@“?","b":"Пиесата, с която @@k@@ проверява дали @@o@@ е убиецът.","tg":"@@2m@@"},{"id":"mon8-lit-hamlet-fc-3","f":"Кого @@2e@@ @@k@@ по погрешка?","b":"@@3b@@, скрит зад завесата.","tg":"@@2m@@"},{"id":"mon8-lit-hamlet-fc-4","f":"@@d@@","b":"Между @@3x@@ да @@42@@ и съмненията и съвестта му.","tg":"Конфликт"},{"id":"mon8-lit-hamlet-fc-5","f":"Как умира @@2r@@?","b":"Пие от отровното вино, приготвено от @@o@@ за @@k@@.","tg":"@@36@@"},{"id":"mon8-lit-hamlet-fc-6","f":"Защо @@k@@ е ренесансов @@4g@@?","b":"@@1b@@ @@4j@@, съмнява се и @@3c@@ морално, вместо сляпо да следва @@3x@@.","tg":"@@1r@@"}],"q":[{"id":1,"qu":"Кой е убиецът на бащата на @@k@@?","op":["Полоний","Клавдий","Лаерт","Фортинбрас"],"ci":1,"ex":"Убиецът на бащата на Хамлет е Клавдий — братът на краля, който го отравя и заема трона. Полоний е съветникът, Лаерт — синът му, а Фортинбрас — норвежкият принц."},{"id":2,"qu":"Защо @@k@@ @@2f@@ пиесата „@@21@@“?","op":["За да провери дали Клавдий е виновен","За да забавлява двора и да скрие плановете си","За да спечели отново Офелия","За да убеди майка си да напусне Клавдий"],"ci":0,"ex":"Хамлет поставя „Мишеловката“, за да провери дали Клавдий е виновен — реакцията на краля при сцената с убийството го издава. Целта не е забавление на двора или спечелване на Офелия."},{"id":3,"qu":"Къде се развива @@3o@@?","op":["В Лондон, Англия","Във Витенберг, Германия","В Париж, Франция","В Елсинор, Дания"],"ci":3,"ex":"Действието се развива в Елсинор — датския кралски замък. Витенберг е университетът, където е учил Хамлет, а Лондон и Париж не са място на действието."},{"id":4,"qu":"@@d@@","op":["Между любовта към Офелия и желанието за власт","Между верността към майка си и към Клавдий","Между дълга да отмъсти и съмнението и съвестта","Между Дания и Норвегия"],"ci":2,"ex":"Вътрешният конфликт на Хамлет е между дълга да отмъсти и съмнението и съвестта му — затова се колебае. Властта и отношенията между Дания и Норвегия не са в центъра на конфликта му."},{"id":5,"qu":"Как @@5e@@ и @@o@@ искат да убият @@k@@?","op":["С нападение в двореца по време на пиесата","С отровна шпага и отровно вино","С капан по време на лов в гората","С пожар в покоите на Хамлет"],"ci":1,"ex":"Лаерт и Клавдий подготвят двубой с отровна шпага, а като резерва — отровено вино. Нападение по време на пиесата, капан на лов или пожар не са част от плана."},{"id":6,"qu":"Кое описва най-точно @@k@@ като ренесансов @@4g@@?","op":["Мисли, съмнява се и преценява сам","Изпълнява сляпо волята на баща си","Действа бързо, без да мисли за последиците","Стреми се преди всичко към трона"],"ci":0,"ex":"Хамлет е ренесансов герой, защото мисли, съмнява се и преценява сам — интересът към разума и вътрешния свят е ренесансова черта. Той не действа сляпо или прибързано и не се стреми към трона."}],"qq":["Защо @@k@@ се колебае?","Какви са конфликтите в „@@k@@“?","Кои са ренесансовите черти в @@1c@@?"]},{"s":"@@3@@","g":"8. клас","st":"syllabus","id":"mon8-lit-shakespeare-sonnets","m":["8-lit:III.4"],"t":"Сонети 91 и 130 (У. @@2j@@): сонетът като жанр","o":"Сонет — 14 стиха. Шекспиров @@2c@@: три @@p@@ и @@4w@@ @@1f@@. Сонет 91: @@1j@@ е по-ценна от всички богатства. Сонет 130: @@64@@ без изкуствени @@11@@.","su":{"ov":"@@5f@@ е @@19@@ жанр със строга форма — @@n@@ от 14 стиха. @@2j@@ пише @@2@@ @@4x@@ (английски) @@2c@@ се състои от три @@p@@ и @@4w@@ @@1f@@. В @@3d@@ често е обратът или изводът на цялото @@n@@.","kp":["Жанрови @@5y@@: 14 стиха; строга рима и ритъм; @@5j@@ на една мисъл или едно @@1k@@; обрат или извод в края. Италианският @@2c@@ (на Петрарка) има две @@p@@ и две тристишия, а @@4x@@ — три @@p@@ и @@1f@@.","Сонет 91 („Един се хвали с ловкост и успехи...“): @@22@@ се гордеят с различни неща — произход, умения, @@4y@@, сила, дрехи, ловни соколи и коне. За @@1a@@ @@s@@ най-голямото @@4y@@ е @@1j@@. Тя е по-ценна от всичко това. Единственият му страх е да не я загуби.","Сонет 130 („Очите ѝ не са звезди...“): @@31@@ @@s@@ отказва да описва @@64@@ с общоприетите поетични @@11@@ — с небесни светила, корали, рози, сняг. Тя е обикновена, земна жена. В @@3d@@ той казва, че @@1j@@ му към нея е не по-малко ценна от @@1j@@, възпявана с фалшиви @@11@@.","@@1r@@: @@2c@@ 130 @@3u@@ шаблонната любовна @@1x@@ и @@3s@@ истинското, неукрасено @@1k@@. Сонет 91 @@2f@@ @@1j@@ над материалните и обществените ценности.","Ренесансов план: @@2w@@ и неговото земно @@1k@@ са в @@10@@. Любимата е реална жена, а не идеализиран небесен @@2s@@."],"eg":"В анализа на @@2c@@ винаги стигай до @@3d@@: то обръща или обобщава мисълта на @@4c@@ строфи. Без него @@2x@@ е непълно.","ct":["Сонет 130 не обижда @@64@@. Той осмива изкуствените поетични @@11@@ и @@3w@@, че @@1e@@ любов не се нуждае от тях.","@@5f@@ е @@19@@ жанр, а не @@3q@@, макар @@2j@@ да е и автор на @@5t@@."],"fd":[{"l":"Сонет","v":"@@19@@ жанр от 14 стиха"},{"l":"Шекспиров @@2c@@","v":"4 + 4 + 4 + 2 (три @@p@@ + @@1f@@)"},{"l":"Петрарков @@2c@@","v":"4 + 4 + 3 + 3"},{"l":"Сонетите на @@2j@@","v":"@@2@@"}]},"nc":[{"id":"mon8-lit-sonnets-chk-1","r":"Схема на строежа на Шекспировия @@2c@@","wn":"@@3i@@ на @@4u@@ @@5y@@ на сонета е @@30@@ @@27@@.","e6":true,"sn":"3 @@p@@ (@@5j@@) + @@1f@@ (обрат/извод)."},{"id":"mon8-lit-sonnets-chk-2","r":"Идеята на всеки от двата сонета в едно изречение","wn":"@@53@@ е основата на писмения анализ.","e6":false,"sn":"91 — @@1j@@ е най-голямото @@4y@@. 130 — @@1e@@ любов не се нуждае от фалшиви @@11@@."}],"fc":[{"id":"mon8-lit-sonnets-fc-1","f":"@@e@@","b":"14 стиха.","tg":"Жанр"},{"id":"mon8-lit-sonnets-fc-2","f":"Какъв е строежът на Шекспировия @@2c@@?","b":"Три @@p@@ и @@4w@@ @@1f@@.","tg":"Жанр"},{"id":"mon8-lit-sonnets-fc-3","f":"@@2b@@ е ролята на @@3d@@?","b":"Обрат или извод — обобщава мисълта на @@z@@.","tg":"Жанр"},{"id":"mon8-lit-sonnets-fc-4","f":"@@f@@","b":"Любовта е по-ценна от @@4e@@, богатството и всички неща, с които @@22@@ се гордеят.","tg":"@@1r@@"},{"id":"mon8-lit-sonnets-fc-5","f":"@@g@@","b":"Шаблонните поетични @@11@@ в любовната @@1x@@.","tg":"@@1r@@"},{"id":"mon8-lit-sonnets-fc-6","f":"Колко сонета пише @@2j@@?","b":"@@2@@","tg":"Факт"}],"q":[{"id":1,"qu":"@@e@@","op":["12","14","16","10"],"ci":1,"ex":"Сонетът е стихотворение от 14 стиха. 12, 16 и 10 стиха не отговарят на жанра."},{"id":2,"qu":"Как е построен @@4x@@ @@2c@@?","op":["Три четиристишия и двустишие","Две четиристишия и две тристишия","Четири тристишия и двустишие","Седем двустишия"],"ci":0,"ex":"Шекспировият (английски) сонет е изграден от три четиристишия и заключително двустишие (4 + 4 + 4 + 2). Две четиристишия и две тристишия са италианският (Петраркин) сонет."},{"id":3,"qu":"@@l@@ е най-голямото @@4y@@ за @@1a@@ @@s@@ в @@2c@@ 91?","op":["Знатният произход","Богатството","Славата","Любовта"],"ci":3,"ex":"В сонет 91 любовта е най-голямото богатство за лирическия говорител — по-ценна от произхода, богатството и всичко, с което другите се хвалят."},{"id":4,"qu":"@@l@@ прави @@2c@@ 130?","op":["Възхвалява любимата чрез небесни и възвишени сравнения","Оплаква изгубената любов и самотата","Осмива шаблонните сравнения и утвърждава истинската любов","Осмива любимата заради външността ѝ"],"ci":2,"ex":"Сонет 130 осмива шаблонните, изкуствени сравнения в любовната лирика и утвърждава истинската любов към реалната жена. Той не я възхвалява с небесни образи и не я осмива."},{"id":5,"qu":"Към кой @@1z@@ род е сонетът?","op":["Епос","Лирика","Драма","Лироепос"],"ci":1,"ex":"Сонетът е лирически жанр — изразява чувства и размисли. Епосът разказва, драмата е за сцената, а лироепосът съчетава разказ и чувство."},{"id":6,"qu":"@@2b@@ е ролята на заключителното @@1f@@?","op":["Дава обрат или извод на стихотворението","Въвежда нова тема, несвързана с началото","Повтаря дословно първото четиристишие","Описва природата като фон на чувството"],"ci":0,"ex":"Заключителното двустишие на Шекспировия сонет дава обрат или извод, като обобщава мисълта на трите четиристишия. То не въвежда несвързана тема и не повтаря началото."}],"qq":["Какъв е строежът на сонета?","@@g@@","@@f@@"]}]);
